<script setup>
import { onMounted,ref } from 'vue'
import { api,send,money } from '../api'
const products=ref([]),orders=ref([]),stats=ref(null),tab=ref('orders'),error=ref(''),message=ref(''),busy=ref(false),editing=ref(null),tracking=ref({}),loading=ref(true)
const labels={PENDING:'待付款',PAID:'待发货',SHIPPED:'已发货',CANCELLED:'已取消'}
async function load(){try{[products.value,orders.value,stats.value]=await Promise.all([api('/admin/products'),api('/admin/orders'),api('/admin/dashboard')])}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(product){editing.value=product?{...product}:{name:'',category:'Home',description:'',price:1,stock:0,image:'/images/cup.svg',active:true};message.value='';error.value=''}
async function save(){busy.value=true;error.value='';try{const p=editing.value;await api('/admin/products'+(p.id?'/'+p.id:''),send(p.id?'PUT':'POST',p));editing.value=null;message.value='商品已保存';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function ship(order){busy.value=true;error.value='';try{await api('/admin/orders/'+order.id+'/ship',send('POST',{tracking:tracking.value[order.id]}));message.value='订单已发货';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page admin-page"><div class="page-title"><div><p class="subtle">HARBORCART OPERATIONS</p><h1>运营工作台</h1></div><span class="badge">中国仓 · 跨境直发</span></div><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="loading">正在载入运营数据…</p><div v-if="stats" class="stats"><div><span>订单总数</span><strong>{{stats.orders}}</strong></div><div><span>等待发货</span><strong>{{stats.pendingShipment}}</strong></div><div><span>低库存商品</span><strong>{{stats.lowStock}}</strong></div><div><span>已付款销售额（按币种）</span><strong class="sales" v-if="stats.sales.length">{{stats.sales.map(s=>money(s.total,s.currency)).join(' / ')}}</strong><strong v-else>—</strong></div></div><div class="admin-toolbar"><div class="tabs"><button :class="{active:tab==='orders'}" @click="tab='orders'">订单履约</button><button :class="{active:tab==='products'}" @click="tab='products'">商品与库存</button></div><button v-if="tab==='products'" class="button small" @click="edit(null)">＋ 新增商品</button></div>
<template v-if="tab==='orders'"><p v-if="!orders.length&&!loading" class="empty">暂无订单。使用买家账户下单后，这里会显示履约任务。</p><article v-for="o in orders" :key="o.id" class="order"><div class="order-heading"><div><h3>HC-{{String(o.id).padStart(6,'0')}} <span class="muted">{{o.email}}</span></h3><p>{{o.recipient}} · {{o.country}} · {{o.address}}</p></div><span class="badge" :class="o.status">{{labels[o.status]}}</span></div><div class="order-lines"><div v-for="item in o.items" :key="item.id"><span>{{item.name}} × {{item.quantity}}</span><strong>{{money(item.unit_price*item.quantity,o.currency)}}</strong></div></div><div class="order-bottom"><strong>合计 {{money(o.total,o.currency)}}</strong><form v-if="o.status==='PAID'" class="ship-form" @submit.prevent="ship(o)"><input v-model="tracking[o.id]" required maxlength="80" aria-label="物流单号" placeholder="输入物流单号"><button class="button small" :disabled="busy">确认发货</button></form><span v-if="o.tracking">物流单号：{{o.tracking}}</span></div></article></template>
<template v-else><form v-if="editing" class="product-editor" @submit.prevent="save"><div class="section-heading"><h2>{{editing.id?'编辑商品':'新增商品'}}</h2><button type="button" class="text-button" @click="editing=null">关闭编辑</button></div><div class="form-two"><label>商品名称<input v-model="editing.name" required maxlength="120"></label><label>分类<select v-model="editing.category"><option>Home</option><option>Travel</option><option>Desk</option></select></label><label>USD 单价<input v-model.number="editing.price" type="number" min="0.01" max="999999.99" step="0.01" required></label><label>可售库存<input v-model.number="editing.stock" type="number" min="0" max="1000000" required></label><label>商品插画<select v-model="editing.image"><option v-for="image in ['bottle','bag','lamp','cup','pouch','stand']" :key="image" :value="'/images/'+image+'.svg'">{{image}}</option></select></label><label>销售状态<select v-model="editing.active"><option :value="true">在售</option><option :value="false">下架</option></select></label></div><label>商品描述<textarea v-model="editing.description" required maxlength="1200" rows="3"></textarea></label><p class="fine-print">库存为当前可售数量的绝对值；编辑前请确认线下盘点结果。</p><button class="button" :disabled="busy">{{busy?'保存中…':'保存商品'}}</button></form><div class="table-scroll"><table><thead><tr><th>商品</th><th>分类</th><th>USD 单价</th><th>库存</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td class="table-product"><img :src="p.image" alt=""><strong>{{p.name}}</strong></td><td>{{p.category}}</td><td>{{money(p.price)}}</td><td><span :class="{warning:p.stock<10}">{{p.stock}}</span></td><td>{{p.active?'在售':'已下架'}}</td><td><button class="text-button" @click="edit(p)">编辑</button></td></tr></tbody></table></div></template>
</section></template>
